import numpy as np


def construct(budget_seconds, start):
    """Code Zero: keep the start if there is one, otherwise a constant function (C = 2)."""
    if start is not None:
        return np.asarray(start, dtype=float)
    return np.ones(50)

import numpy as np
import time


def _conv_max(h):
    return np.max(np.convolve(h, h))


def _C_fast(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * _conv_max(h) / (s * s)


def _C_and_grad(h):
    n = len(h)
    s = h.sum()
    if s <= 0:
        return np.inf, np.zeros(n)
    conv = np.convolve(h, h)
    k = int(np.argmax(conv))
    m = conv[k]
    C = 2.0 * n * m / (s * s)
    dM = np.zeros(n)
    i0 = max(0, k - n + 1)
    i1 = min(n - 1, k)
    if i1 >= i0:
        idx = np.arange(i0, i1 + 1)
        dM[idx] = 2.0 * h[k - idx]
    g = 2.0 * n / (s * s) * (dM - 2.0 * m / s)
    return C, g


def _descent(h, deadline, lr=0.02, max_stall=60):
    h = np.maximum(h.copy(), 0.0)
    if h.sum() <= 0:
        return np.inf, h
    C, g = _C_and_grad(h)
    best_C, best_h = C, h.copy()
    mom = np.zeros_like(h)
    beta = 0.9
    step = lr
    stall = 0
    while time.process_time() < deadline:
        C, g = _C_and_grad(h)
        gn = np.linalg.norm(g)
        if gn > 1e-15:
            g = g / gn
        mom = beta * mom + g
        h = np.maximum(h - step * mom, 0.0)
        if h.sum() <= 0:
            h = best_h.copy()
            mom[:] = 0
            step *= 0.5
            continue
        C2 = _C_fast(h)
        if C2 < best_C - 1e-13:
            best_C, best_h = C2, h.copy()
            stall = 0
            step *= 1.05
        else:
            stall += 1
            if stall % 5 == 0:
                step *= 0.85
            if stall > max_stall:
                h = best_h.copy()
                mom[:] = 0
                step *= 0.5
                stall = 0
                if step < 1e-8:
                    break
    return best_C, best_h


def _local_polish(h, deadline, rng):
    h = h.copy()
    n = len(h)
    C = _C_fast(h)
    best_C, best_h = C, h.copy()
    scale = np.mean(h) + 1e-12
    step = 0.05 * scale
    stall = 0
    while time.process_time() < deadline:
        k = max(1, int(n * rng.uniform(0.01, 0.08)))
        idx = rng.integers(0, n, size=k)
        cand = h.copy()
        cand[idx] = np.maximum(cand[idx] + rng.normal(0, step, size=k), 0.0)
        cc = _C_fast(cand)
        if cc < C - 1e-14:
            h = cand
            C = cc
            if cc < best_C:
                best_C, best_h = cc, cand.copy()
            stall = 0
        else:
            stall += 1
            if stall % 30 == 0:
                step *= 0.92
                if step < 1e-6 * scale:
                    step = 0.05 * scale
    return best_C, best_h


def _refine(h, deadline, rng, rounds=4):
    C = _C_fast(h)
    best_C, best_h = C, h.copy()
    for r in range(rounds):
        if time.process_time() >= deadline:
            break
        sub = time.process_time() + (deadline - time.process_time()) * 0.5
        c, hh = _descent(best_h, sub)
        if c < best_C:
            best_C, best_h = c, hh
        c, hh = _local_polish(best_h, deadline, rng)
        if c < best_C:
            best_C, best_h = c, hh
    return best_C, best_h


def _smooth(h, k):
    """Box smoothing by window k."""
    if k <= 1:
        return h.copy()
    ker = np.ones(k) / k
    return np.convolve(h, ker, mode='same')


def _upsample_refine(h, N, deadline, rng):
    xold = np.linspace(0, 1, len(h))
    xnew = np.linspace(0, 1, N)
    h0 = np.maximum(np.interp(xnew, xold, h), 0.0)
    return _refine(h0, deadline, rng, rounds=2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    limit = t0 + budget_seconds - 1.5
    rng = np.random.default_rng(987654321)

    candidates = []
    for N in (60, 120, 240, 400):
        x = np.linspace(-1, 1, N)
        candidates.append((_C_fast(np.cos(np.pi * x / 2.0) ** 2),
                            np.cos(np.pi * x / 2.0) ** 2))
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            candidates.append((_C_fast(s), s.copy()))

    candidates.sort(key=lambda t: t[0])
    best_C, best_h = candidates[0]
    print(f"init C={best_C:.6f} N={len(best_h)}")

    # 1) Refine best seed
    d1 = t0 + (limit - t0) * 0.45
    c, h = _refine(best_h, d1, rng, rounds=3)
    if c < best_C:
        best_C, best_h = c, h
        print(f"refine C={best_C:.6f} N={len(best_h)}")

    # 2) Smoothing schedule: smooth then refine at multiple scales
    smooth_ks = [1, 2, 3, 5, 8]
    for i, k in enumerate(smooth_ks):
        if time.process_time() >= limit - 0.9:
            break
        if k == 1:
            h0 = best_h.copy()
        else:
            h0 = _smooth(best_h, k)
        sub_deadline = t0 + (limit - t0) * (0.45 + 0.35 * (i + 1) / len(smooth_ks))
        sub_deadline = min(sub_deadline, limit - 0.6)
        c, h = _refine(h0, sub_deadline, rng, rounds=2)
        if c < best_C - 1e-10:
            best_C, best_h = c, h
            print(f"smooth k={k} C={best_C:.6f} N={len(best_h)}")

    # 3) Upsample to larger N
    Ns = [800, 1200, 2000, 3500]
    for i, N in enumerate(Ns):
        if time.process_time() >= limit - 0.7:
            break
        sub_deadline = t0 + (limit - t0) * (0.80 + 0.20 * (i + 1) / len(Ns))
        sub_deadline = min(sub_deadline, limit - 0.3)
        c, h = _upsample_refine(best_h, N, sub_deadline, rng)
        if c < best_C - 1e-10:
            best_C, best_h = c, h
            print(f"upsample N={N} C={best_C:.6f}")

    # 4) Final polish
    if time.process_time() < limit - 0.15:
        c, h = _local_polish(best_h, limit - 0.05, rng)
        if c < best_C:
            best_C, best_h = c, h
            print(f"polish C={best_C:.6f}")

    print(f"final C={best_C:.6f} N={len(best_h)}")
    return np.asarray(best_h, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve, correlate


class _Timeout(Exception):
    pass


def _C_fast(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _C_fft(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(fftconvolve(h, h)) / (s * s)


def _smooth_C_grad(h, beta=300.0):
    n = len(h)
    s = h.sum()
    if s <= 0:
        return 1e10, np.zeros(n)
    conv = fftconvolve(h, h)
    m = conv.max()
    if m <= 0:
        return 1e10, np.zeros(n)
    z = beta * (conv - m)
    ez = np.exp(z)
    Z = ez.sum()
    lse = m + np.log(Z) / beta
    w = ez / Z
    corr = correlate(w, h, mode='valid', method='fft')
    C = 2.0 * n * lse / (s * s)
    g = 4.0 * n / (s * s) * corr - 4.0 * n * lse / (s ** 3)
    return C, g


def _lbfgs(h0, deadline, maxiter, beta=300.0):
    n = len(h0)
    def obj(h):
        if time.process_time() > deadline:
            raise _Timeout()
        hc = np.maximum(h, 0.0)
        C, g = _smooth_C_grad(hc, beta)
        g = g.copy()
        g[h < 0] = 0.0
        return C, g
    try:
        res = minimize(obj, h0.copy(), jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * n,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 2,
                                'ftol': 1e-16, 'gtol': 1e-14,
                                'maxcor': 20})
        h = np.maximum(res.x, 0.0)
    except _Timeout:
        return None, None
    return _C_fft(h), h


def _resample(h, N):
    xold = np.linspace(0, 1, len(h))
    xnew = np.linspace(0, 1, N)
    return np.maximum(np.interp(xnew, xold, h), 0.0)


def _refine_coord(h, deadline, rng, n_sweeps=3):
    n = len(h)
    h = h.copy()
    C = _C_fast(h)
    best_C, best_h = C, h.copy()
    scale = np.mean(h) + 1e-12
    for _ in range(n_sweeps):
        if time.process_time() >= deadline:
            break
        idx = rng.permutation(n)
        improved = False
        for j in idx:
            if time.process_time() >= deadline:
                break
            old = h[j]
            for delta in (0.2, 0.05, 0.01, 0.002):
                cand = h.copy()
                cand[j] = max(0.0, old + delta * scale)
                cc = _C_fast(cand)
                if cc < C - 1e-15:
                    h = cand; C = cc; improved = True; break
                cand[j] = max(0.0, old - delta * scale)
                cc = _C_fast(cand)
                if cc < C - 1e-15:
                    h = cand; C = cc; improved = True; break
        if C < best_C:
            best_C, best_h = C, h.copy()
        if not improved:
            break
    return best_C, best_h


def construct(budget_seconds, start):
    t0 = time.process_time()
    limit = t0 + budget_seconds - 1.5
    rng = np.random.default_rng(20240101)

    best_C = np.inf
    best_h = None
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best_C = _C_fast(s)
            best_h = s.copy()
            print(f"start C={best_C:.6f} N={len(s)}")

    if best_h is None:
        N = 200
        x = np.linspace(-1, 1, N)
        c = np.cos(np.pi * x / 2.0) ** 2
        best_C = _C_fast(c)
        best_h = c
        print(f"init C={best_C:.6f} N={N}")

    # Multi-beta L-BFGS at current resolution
    for beta in (100.0, 300.0, 1000.0):
        if time.process_time() >= limit - 0.5:
            break
        c, h = _lbfgs(best_h, min(limit - 0.3, time.process_time() + 3.0), 3000, beta)
        if c is not None and c < best_C:
            best_C, best_h = c, h
        print(f"lbfgs beta={beta} C={best_C:.6f} N={len(best_h)}")

    # Progressive N increase
    Ns = [400, 800, 1500, 2500, 4000, 6000, 9000, 13000]
    for i, N in enumerate(Ns):
        if time.process_time() >= limit - 0.5:
            break
        h0 = _resample(best_h, N)
        sub = t0 + (limit - t0) * (0.30 + 0.65 * (i + 1) / len(Ns))
        sub = min(sub, limit - 0.3)
        c, h = _lbfgs(h0, sub, 2000, 300.0)
        if c is not None and c < best_C:
            best_C, best_h = c, h
        print(f"N={N} lbfgs C={best_C:.6f}")

    # final polish at low N
    if time.process_time() < limit - 0.2 and len(best_h) <= 2000:
        c, h = _refine_coord(best_h, limit - 0.05, rng, n_sweeps=5)
        if c < best_C:
            best_C, best_h = c, h
            print(f"final coord C={best_C:.6f} N={len(h)}")

    print(f"final C={best_C:.6f} N={len(best_h)}")
    return np.asarray(best_h, dtype=float)

import numpy as np
import time


def _C_fast(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _C_and_grad(h):
    n = len(h)
    s = h.sum()
    if s <= 0:
        return np.inf, np.zeros(n)
    conv = np.convolve(h, h)
    m = conv.max()
    thresh = m - 1e-12 * max(m, 1.0)
    dM = np.zeros(n)
    nk = 0
    for k in range(len(conv)):
        if conv[k] >= thresh:
            nk += 1
            i0 = max(0, k - n + 1)
            i1 = min(n - 1, k)
            if i1 >= i0:
                idx = np.arange(i0, i1 + 1)
                np.add.at(dM, idx, 2.0 * h[k - idx])
    if nk > 0:
        dM /= nk
    C = 2.0 * n * m / (s * s)
    g = 2.0 * n / (s * s) * (dM - 2.0 * m / s)
    return C, g


def _adam_descent(h, deadline, lr=0.01):
    n = len(h)
    h = np.maximum(h.copy(), 0.0)
    if h.sum() <= 0:
        return np.inf, h
    best_C, best_h = _C_fast(h), h.copy()
    m1 = np.zeros(n); m2 = np.zeros(n)
    b1, b2, eps = 0.9, 0.999, 1e-8
    step = lr; t = 0; stall = 0
    while time.process_time() < deadline:
        t += 1
        C, g = _C_and_grad(h)
        gn = np.linalg.norm(g)
        if gn > 1e-15:
            g = g / gn
        m1 = b1 * m1 + (1 - b1) * g
        m2 = b2 * m2 + (1 - b2) * g * g
        mh = m1 / (1 - b1 ** t)
        vh = m2 / (1 - b2 ** t)
        h = np.maximum(h - step * mh / (np.sqrt(vh) + eps), 0.0)
        if h.sum() <= 0:
            h = best_h.copy(); m1[:] = 0; m2[:] = 0; step *= 0.5; continue
        C2 = _C_fast(h)
        if C2 < best_C - 1e-15:
            best_C, best_h = C2, h.copy(); stall = 0
        else:
            stall += 1
            if stall > 400:
                h = best_h.copy(); m1[:] = 0; m2[:] = 0; step *= 0.5; stall = 0
                if step < 1e-10:
                    break
    return best_C, best_h


def _resample(h, N):
    xold = np.linspace(0, 1, len(h))
    xnew = np.linspace(0, 1, N)
    return np.maximum(np.interp(xnew, xold, h), 0.0)


def _refine(h, deadline, rng):
    n = len(h)
    h = h.copy()
    C = _C_fast(h)
    best_C, best_h = C, h.copy()
    scale = np.mean(h) + 1e-12
    while time.process_time() < deadline:
        idx = rng.permutation(n)
        improved = False
        for j in idx:
            if time.process_time() >= deadline:
                break
            old = h[j]
            for delta in (0.3, 0.1, 0.03, 0.01, 0.003, 0.001):
                cand = h.copy(); cand[j] = max(0.0, old + delta * scale)
                cc = _C_fast(cand)
                if cc < C - 1e-15:
                    h = cand; C = cc; improved = True; break
                cand[j] = max(0.0, old - delta * scale)
                cc = _C_fast(cand)
                if cc < C - 1e-15:
                    h = cand; C = cc; improved = True; break
        if C < best_C:
            best_C, best_h = C, h.copy()
        if not improved:
            break
    return best_C, best_h


def construct(budget_seconds, start):
    t0 = time.process_time()
    limit = t0 + budget_seconds - 0.8
    rng = np.random.default_rng(98765)

    candidates = []
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            candidates.append((_C_fast(s), s.copy()))

    for N in (60, 120, 200, 300):
        x = np.linspace(-1, 1, N)
        c = np.cos(np.pi * x / 2.0) ** 2
        candidates.append((_C_fast(c), c))

    candidates.sort(key=lambda t: t[0])
    best_C, best_h = candidates[0]
    print(f"init C={best_C:.6f} N={len(best_h)}")

    total = limit - t0

    # Phase A: strong line-search polish on the start at its own resolution.
    # Coordinate descent is very effective at low N and the start is N=800.
    if len(best_h) <= 4000:
        dA = min(t0 + total * 0.20, limit - 0.5)
        c, h = _refine(best_h, dA, rng)
        if c < best_C:
            best_C, best_h = c, h
        print(f"polish start C={best_C:.6f} N={len(best_h)}")

    # Phase B: Adam on start at native resolution.
    dB = min(t0 + total * 0.35, limit - 0.5)
    c, h = _adam_descent(best_h, dB, lr=0.004)
    if c < best_C:
        best_C, best_h = c, h
    print(f"adam C={best_C:.6f} N={len(best_h)}")

    # Phase C: progressive refinement.
    Ns = [500, 800, 1200, 1800, 2600, 3600, 5000, 7000]
    for i, N in enumerate(Ns):
        if time.process_time() >= limit - 0.8:
            break
        h0 = _resample(best_h, N)
        sub_deadline = min(t0 + total * (0.35 + 0.60 * (i + 1) / len(Ns)),
                           limit - 0.4)
        c, h = _adam_descent(h0, sub_deadline, lr=0.003)
        if c < best_C:
            best_C, best_h = c, h
        if N <= 2600 and time.process_time() < sub_deadline - 0.05:
            c, h = _refine(best_h, sub_deadline, rng)
            if c < best_C:
                best_C, best_h = c, h
        print(f"N={N} C={best_C:.6f}")

    # Phase D: final line-search polish.
    if time.process_time() < limit - 0.2:
        c, h = _refine(best_h, limit - 0.05, rng)
        if c < best_C:
            best_C, best_h = c, h
            print(f"final refine C={best_C:.6f} N={len(best_h)}")

    print(f"final C={best_C:.6f} N={len(best_h)}")
    return np.asarray(best_h, dtype=float)

