import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve, correlate


class _Timeout(Exception):
    pass


def _C_fast(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _C_fft(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(fftconvolve(h, h)) / (s * s)


def _smooth_C_grad(h, beta=300.0):
    n = len(h)
    s = h.sum()
    if s <= 0:
        return 1e10, np.zeros(n)
    conv = fftconvolve(h, h)
    m = conv.max()
    if m <= 0:
        return 1e10, np.zeros(n)
    z = beta * (conv - m)
    ez = np.exp(z)
    Z = ez.sum()
    lse = m + np.log(Z) / beta
    w = ez / Z
    corr = correlate(w, h, mode='valid', method='fft')
    C = 2.0 * n * lse / (s * s)
    g = 4.0 * n / (s * s) * corr - 4.0 * n * lse / (s ** 3)
    return C, g


def _lbfgs(h0, deadline, maxiter, beta=300.0):
    n = len(h0)
    def obj(h):
        if time.process_time() > deadline:
            raise _Timeout()
        hc = np.maximum(h, 0.0)
        C, g = _smooth_C_grad(hc, beta)
        g = g.copy()
        g[h < 0] = 0.0
        return C, g
    try:
        res = minimize(obj, h0.copy(), jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * n,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 2,
                                'ftol': 1e-16, 'gtol': 1e-14,
                                'maxcor': 20})
        h = np.maximum(res.x, 0.0)
    except _Timeout:
        return None, None
    return _C_fft(h), h


def _resample(h, N):
    xold = np.linspace(0, 1, len(h))
    xnew = np.linspace(0, 1, N)
    return np.maximum(np.interp(xnew, xold, h), 0.0)


def _peak_weights(h, beta):
    conv = fftconvolve(h, h)
    m = conv.max()
    z = beta * (conv - m)
    ez = np.exp(z)
    return ez / ez.sum()


def _refine_coord(h, deadline, rng, n_sweeps=3):
    # Coordinate refinement targeted at the active peak region only.
    n = len(h)
    h = h.copy()
    C = _C_fast(h)
    best_C, best_h = C, h.copy()
    scale = np.mean(h) + 1e-12
    for _ in range(n_sweeps):
        if time.process_time() >= deadline:
            break
        idx = rng.permutation(n)
        improved = False
        for j in idx:
            if time.process_time() >= deadline:
                break
            old = h[j]
            for delta in (0.2, 0.05, 0.01, 0.002):
                cand = h.copy()
                cand[j] = max(0.0, old + delta * scale)
                cc = _C_fast(cand)
                if cc < C - 1e-15:
                    h = cand; C = cc; improved = True; break
                cand[j] = max(0.0, old - delta * scale)
                cc = _C_fast(cand)
                if cc < C - 1e-15:
                    h = cand; C = cc; improved = True; break
        if C < best_C:
            best_C, best_h = C, h.copy()
        if not improved:
            break
    return best_C, best_h


def _peak_polish(h, deadline, beta=2000.0, iters=40):
    """Gradient step on the true max: descend only the peak set via smoothed gradient."""
    n = len(h)
    h = np.maximum(h.copy(), 0.0)
    C = _C_fft(h)
    best_C, best_h = C, h.copy()
    lr = 1e-3
    for _ in range(iters):
        if time.process_time() >= deadline:
            break
        Ch, g = _smooth_C_grad(h, beta)
        # normalize gradient step in height scale
        gn = np.linalg.norm(g)
        if gn == 0:
            break
        step = lr * h.sum() / (gn + 1e-12)
        h2 = np.maximum(h - step * g, 0.0)
        c2 = _C_fft(h2)
        if c2 < C - 1e-14:
            h = h2; C = c2
            if C < best_C:
                best_C, best_h = C, h.copy()
        else:
            lr *= 0.5
            if lr < 1e-9:
                break
    return best_C, best_h


def construct(budget_seconds, start):
