        best_C = _C_fast(c)
        best_h = c
        print(f"init C={best_C:.6f} N={N}")

    base_N = len(best_h)
    cand_Ns = sorted(set([max(50, base_N // 2), base_N, min(20000, base_N * 2)]))

    for it in range(8):
        if time.process_time() >= limit - 0.5:
            break
        N = cand_Ns[it % len(cand_Ns)]
        h0 = _resample(best_h, N)
        if it > 0 and time.process_time() < limit - 1.0:
            h0 = np.maximum(h0 * (1.0 + 0.001 * rng.standard_normal(len(h0))), 0.0)
        sub = min(limit - 0.3, time.process_time() + 2.5)
        c, h = _lbfgs(h0, sub, 2000, 300.0)
        if c is not None and c < best_C:
            best_C, best_h = c, h
            print(f"it={it} N={N} lbfgs C={best_C:.6f}")
        else:
            if time.process_time() < limit - 1.0:
                sub = min(limit - 0.3, time.process_time() + 1.5)
                c, h = _lbfgs(h0, sub, 1500, 1000.0)
                if c is not None and c < best_C:
                    best_C, best_h = c, h
                    print(f"it={it} N={N} lbfgs b=1000 C={best_C:.6f}")

    # Sharp-max polish: directly minimize the true max via smoothed-gradient steps.
    for beta in (500.0, 2000.0, 8000.0):
        if time.process_time() >= limit - 0.3:
            break
        c, h = _peak_polish(best_h, limit - 0.2, beta=beta, iters=30)
        if c < best_C:
            best_C, best_h = c, h
            print(f"peak polish b={beta:.0f} C={best_C:.6f} N={len(h)}")

    if time.process_time() < limit - 0.3 and len(best_h) <= 2000:
        c, h = _refine_coord(best_h, limit - 0.05, rng, n_sweeps=5)
        if c < best_C:
