    # Coordinate polish on the current best if small enough.
    if time.process_time() < limit - 0.3 and len(best_h) <= 3000:
        c, h = _refine_coord(best_h, limit - 0.05, rng, n_sweeps=5)
        if c < best_C:
            best_C, best_h = c, h
            print(f"final coord C={best_C:.6f} N={len(h)}")

    print(f"final C={best_C:.6f} N={len(best_h)}")
    return np.asarray(best_h, dtype=float)

