import numpy as np
import time
from scipy.signal import fftconvolve, correlate


class _Timeout(Exception):
    pass


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _C_fft(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(fftconvolve(h, h)) / (s * s)


def _smooth_C_grad(h, beta):
    """Gradient of softmax-smoothed C with respect to h."""
    n = len(h)
    s = h.sum()
    if s <= 0:
        return 1e10, np.zeros(n)
    conv = fftconvolve(h, h)
    m = conv.max()
    z = beta * (conv - m)
    ez = np.exp(z)
    Z = ez.sum()
    lse = m + np.log(Z) / beta
    w = ez / Z
    corr = correlate(w, h, mode='valid', method='fft')
    C = 2.0 * n * lse / (s * s)
    g = 4.0 * n / (s * s) * corr - 4.0 * n * lse / (s ** 3)
    return C, g


def _resample(h, N):
    if len(h) == N:
        return h.copy()
    xold = np.linspace(0, 1, len(h))
    xnew = np.linspace(0, 1, N)
    return np.maximum(np.interp(xnew, xold, h), 0.0)


def _grad_refine(h, deadline, beta, lr=0.5, max_iter=200):
    """Gradient descent on smoothed C with backtracking line search."""
    n = len(h)
    h = np.maximum(h.copy(), 0.0)
    C = _C_fft(h)
    best_C, best_h = C, h.copy()
    scale = h.sum() / max(1, np.count_nonzero(h)) + 1e-12
    for _ in range(max_iter):
        if time.process_time() >= deadline:
            break
        Ch, g = _smooth_C_grad(h, beta)
        gn = np.linalg.norm(g)
        if gn < 1e-14:
            break
        step = lr * scale * n / (gn + 1e-12)
        accepted = False
        while step > 1e-12:
            h2 = np.maximum(h - step * g, 0.0)
            c2 = _C_fft(h2)
            if c2 < C - 1e-15:
                h = h2; C = c2
                accepted = True
                if C < best_C:
                    best_C, best_h = C, h.copy()
                lr = min(lr * 1.2, 1.0)
                break
            step *= 0.5
        if not accepted:
            lr *= 0.5
            if lr < 1e-10:
                break
    return best_C, best_h


def _peak_polish(h, deadline, beta, iters=60):
    """Polish by sharpening the peak: only the maximum region matters."""
    n = len(h)
    h = np.maximum(h.copy(), 0.0)
    C = _C_fft(h)
    best_C, best_h = C, h.copy()
    lr = 1e-2
    for _ in range(iters):
        if time.process_time() >= deadline:
            break
        Ch, g = _smooth_C_grad(h, beta)
        gn = np.linalg.norm(g)
        if gn == 0:
            break
        step = lr * h.sum() / (gn + 1e-12)
        h2 = np.maximum(h - step * g, 0.0)
        c2 = _C_fft(h2)
        if c2 < C - 1e-15:
            h = h2; C = c2
            if C < best_C:
                best_C, best_h = C, h.copy()
            lr = min(lr * 1.3, 1.0)
        else:
            lr *= 0.6
            if lr < 1e-10:
                break
    return best_C, best_h


def construct(budget_seconds, start):
    t0 = time.process_time()
    limit = t0 + budget_seconds - 1.2
    rng = np.random.default_rng(777)

    best_C = np.inf
    best_h = None
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best_C = _C_fft(s)
            best_h = s.copy()
            print(f"start C={best_C:.6f} N={len(s)}")

    if best_h is None:
        N = 400
        x = np.linspace(-1, 1, N)
        c = np.cos(np.pi * x / 2.0) ** 2
        best_C = _C_fft(c)
        best_h = c
        print(f"init C={best_C:.6f} N={N}")

    # Multi-scale gradient descent at progressively sharp betas and sizes.
    base_N = len(best_h)
    sizes = [base_N]
    for mult in (1.25, 1.5, 2.0):
        nn = min(30000, int(base_N * mult))
        if nn not in sizes:
            sizes.append(nn)
    # Also try downsampling (helps when start is finely resolved).
    for div in (0.75, 0.5):
        nn = max(50, int(base_N * div))
        if nn not in sizes:
            sizes.append(nn)

    for N in sizes:
        if time.process_time() >= limit - 0.5:
            break
        h0 = _resample(best_h, N)
        c = _C_fft(h0)
        # progressive beta sharpening
        for beta in (100.0, 400.0, 1500.0, 5000.0, 20000.0):
            if time.process_time() >= limit - 0.3:
                break
            sub = min(limit - 0.2, time.process_time() + 0.6)
            c, h = _grad_refine(h0, sub, beta, lr=0.3, max_iter=60)
            if c < best_C:
                best_C, best_h = c, h.copy()
                h0 = h.copy()
        print(f"N={N} refine C={best_C:.6f}")

    # Final sharpening on best shape.
    for beta in (5000.0, 20000.0, 80000.0):
        if time.process_time() >= limit - 0.2:
            break
        c, h = _peak_polish(best_h, limit - 0.1, beta=beta, iters=80)
        if c < best_C:
            best_C, best_h = c, h
            print(f"peak b={beta:.0f} C={best_C:.6f} N={len(h)}")

    print(f"final C={best_C:.6f} N={len(best_h)}")
    return np.asarray(best_h, dtype=float)

