    hs = _symmetrize(best_h)
    cs = _C(hs)
    if cs < best_C:
        best_C, best_h = cs, hs
        print(f"final sym C={best_C:.7f}")

    print(f"final C={best_C:.7f} N={len(best_h)}")
    return np.asarray(best_h, dtype=float)

