        h = np.maximum(res.x, 0.0)
    except _Timeout:
        return None, None
    return _C(h), h

def _tilt(h, delta):
    # multiplicative tilt on support to fight the flat top; keeps positivity
    h = h.copy()
    n = len(h)
    x = np.linspace(-1, 1, n)
    # parabolic bump to concentrate mass toward center
    w = 1.0 + delta * (1.0 - x * x)
    return np.maximum(h * w, 0.0)

def construct(budget_seconds, start):
    t0 = time.process_time()
    limit = t0 + budget_seconds - 0.7

